from baseline_registry import ROOT,REPO,ref,sha,dump
src=ROOT/'validation/integrated'/sys.argv[1];out=ROOT/'validation/integrated'/sys.argv[2];out.mkdir();shutil.copyfile(__file__,out/'producer.py');s=json.loads((src/'summary.json').read_text());assert sha(REPO/s['STEP']['path'])==s['STEP']['SHA256'];cp=REPO/s['candidate']['path'];assert sha(cp)==s['candidate']['SHA256'];a=np.load(src/'field.npz');p=a['points_mm'];t=a['tetra'];u=a['displacement_mm'];F=a['load_N'];reaction=a['reaction_N'];floor=a['floor_nodes'];E=s['E_ASSUMED_MPa'];nu=s['nu_ASSUMED'];mu=E/(2*(1+nu));la=E*nu/((1+nu)*(1-2*nu));X=p[t[:,1:]]-p[t[:,0,None]];iv=np.linalg.inv(X);vol=abs(np.linalg.det(X))/6;grad=np.zeros((len(t),4,3));grad[:,1:]=iv.transpose(0,2,1);grad[:,0]=-grad[:,1:].sum(1);G=np.einsum('tai,taj->tij',u[t],grad);eps=.5*(G+G.transpose(0,2,1));sig=2*mu*eps+la*np.trace(eps,axis1=1,axis2=2)[:,None,None]*np.eye(3);internal=np.zeros_like(F);elemforce=np.einsum('tij,taj,t->tai',sig,grad,vol)
